#!/usr/bin/env python3
import cadquery as cq
from pathlib import Path

SPEC = {'kind': 'extrusion', 'center': [0.030422264999999997, 0.17597369499999999, 0.231751845], 'basis': [[-0.0, 0.991412697160069, -0.13077027150617038], [0.6700499304676678, 0.09707286898777882, 0.7359415389735485], [0.7423160315393124, -0.08762261132994752, -0.6642960087968672]], 'axis': [-0.13077027150617038, 0.7359415389735485, -0.6642960087968672], 'zmin': -0.027053384477497923, 'zmax': 0.02035828807946818, 'profiles': [{'outer': [[-0.05206606918578437, 0.025685500542132506], [-0.052781203735784675, 0.030393491863811795], [-0.052852364047569635, 0.0351057849340267], [-0.05223719954621787, 0.039817387103018215], [-0.05097392606990799, 0.044409718903029985], [-0.049024297168608906, 0.04877537951896341], [-0.046468898830807716, 0.05280077960861227], [-0.04342635216623905, 0.05642331037783514], [-0.03985438083158473, 0.05952497680578486], [-0.03591814051627184, 0.06217174576041688], [-0.0315752313773507, 0.06418913169657012], [-0.027024902161360834, 0.06557047583277573], [-0.022309470137277316, 0.06632078782149521], [-0.017589915135577436, 0.06638249389803486], [-0.012866212718797248, 0.06575557597872496], [-0.008299427655921999, 0.06443896257639964], [-0.003969976254973076, 0.0625451648276659], [7.971339378053003e-05, 0.06002261607960021], [0.0036887677486391705, 0.056926743572023174], [0.006818900879236945, 0.05336507924648411], [0.009466053199645486, 0.04940463219610435], [0.011469220245373255, 0.04510083036576037], [0.012870662594206638, 0.040561687007388686], [0.013585811990527588, 0.03585370384738415], [0.013656942609671263, 0.03108491367246254], [0.013041790786657105, 0.026373335120137165], [0.011740290961814049, 0.021831936180179867], [0.009790723810330753, 0.017466300435149], [0.007273490071246972, 0.013446443224154253], [0.004192752005963676, 0.00981837560748947], [0.0006207873718086503, 0.006660169884149395], [-0.003315507270159678, 0.004069905534380782], [-0.007620197483707981, 0.002058078309883358], [-0.012170526699697828, 0.0006202137358126465], [-0.01688597140211894, -7.359151758086907e-05], [-0.021643693170519264, -0.00014081510365628915], [-0.026329196040763496, 0.0004916270257876073], [-0.030895981103638746, 0.0017517199902478615], [-0.035263611949625705, 0.0036965168788987497], [-0.0392751422548392, 0.006224613755107228], [-0.04288417650819994, 0.009320459432489407], [-0.046052509185333663, 0.012876599547894458], [-0.04866146721438351, 0.01684258597202387], [-0.050664614158613376, 0.021146380800426946]], 'holes': []}, {'outer': [[-0.009908637572330166, -0.01957495223048993], [-0.007391411256406696, -0.01555509414326906], [-0.004348884693335941, -0.011932566286232257], [-0.0007387078343073632, -0.00876883256434598], [0.00319755928300275, -0.006178560336410353], [0.007502263620210666, -0.004166733017410356], [0.012052592836200495, -0.002728868443339643], [0.016768030115461314, -0.002035062313720012], [0.021487599963481815, -0.0019733679037595552], [0.02621126289992715, -0.0026002835802694073], [0.03077806806430034, -0.003916884156281706], [0.03514567066296806, -0.005805180624326598], [0.03915720694601984, -0.008333264768724612], [0.04276625006786293, -0.011429115016242511], [0.04593458057701361, -0.014985249590783152], [0.04854351324938827, -0.018951243591736937], [0.050546672871955745, -0.023255034631727827], [0.051948137490270066, -0.02779418061877785], [0.052663272040270395, -0.03250214219807623], [0.05273443616191061, -0.03727092751935439], [0.05211925083639991, -0.04192602022983903], [0.050817791214552696, -0.04652391395503535], [0.04890638938444779, -0.05088402849662083], [0.04635095084365076, -0.054909424496514876], [0.04330836923126356, -0.058531956425471585], [0.03973647974792293, -0.06169014525057871], [0.03576197288108103, -0.06428595742714746], [0.031457283390193755, -0.0662977864985997], [0.026906994377199712, -0.06767913472456014], [0.0222338214855805, -0.06843445081490973], [0.017471938901101283, -0.06849114888906957], [0.012748269264156587, -0.06786423418328841], [0.008181464099783398, -0.06654763360727611], [0.0038520758939722855, -0.06465381468154942], [-0.00019765468043817728, -0.06213125008264714], [-0.0038067030574585278, -0.05903540449976753], [-0.006936848866393892, -0.05547373404851367], [-0.009583999741480394, -0.05151328077791655], [-0.01158714813103228, -0.04720948225560388], [-0.012988598625687004, -0.042670336174051283], [-0.013703745131363894, -0.037962380230119885], [-0.0137748764731686, -0.033193588208243474], [-0.013159726818137454, -0.028481984286799742], [-0.01185825379529162, -0.023940589229757208]], 'holes': []}], 'simplify_tolerance': 2.6974728557420888e-05, 'sketch_entity_count': 88}
OUT = Path(__file__).resolve().parent

def vec(v):
    return cq.Vector(float(v[0]), float(v[1]), float(v[2]))

def build():
    s = SPEC
    kind = s["kind"]
    B = s.get("basis")
    center = s.get("center")
    if kind == "extrusion":
        xdir = [B[i][0] for i in range(3)]
        axis = [B[i][2] for i in range(3)]
        origin = [center[i] + s["zmin"] * axis[i] for i in range(3)]
        plane = cq.Plane(origin=origin, xDir=xdir, normal=axis)
        result = None
        height = s["zmax"] - s["zmin"]
        for profile in s["profiles"]:
            solid = cq.Workplane(plane).polyline(profile["outer"]).close().extrude(height)
            for hole in profile["holes"]:
                cutter = cq.Workplane(plane).polyline(hole).close().extrude(height)
                solid = solid.cut(cutter)
            result = solid if result is None else result.union(solid)
    elif kind == "multi_loft":
        def loft(track):
            wires = [cq.Wire.makePolygon([vec(p) for p in section], close=True) for section in track]
            return cq.Solid.makeLoft(wires, ruled=bool(s.get("ruled", True)))
        outer = [loft(track) for track in s["outer_tracks"]]
        # Keep disjoint solids as a legal STEP compound.  Global Boolean fusion
        # is unnecessary for training geometry and scales poorly with profiles.
        for track in s.get("hole_tracks", []):
            cutter = loft(track)
            cut_outer = []
            for solid in outer:
                try:
                    cut_outer.append(solid.cut(cutter))
                except Exception:
                    cut_outer.append(solid)
            outer = cut_outer
        result = outer[0] if len(outer) == 1 else cq.Compound.makeCompound(outer)
    elif kind == "box":
        xdir = [B[i][0] for i in range(3)]
        axis = [B[i][2] for i in range(3)]
        origin = [center[i] + s["mins"][0]*B[i][0] + s["mins"][1]*B[i][1] + s["mins"][2]*B[i][2] for i in range(3)]
        plane = cq.Plane(origin=origin, xDir=xdir, normal=axis)
        dx=s["maxs"][0]-s["mins"][0]; dy=s["maxs"][1]-s["mins"][1]; dz=s["maxs"][2]-s["mins"][2]
        result = cq.Workplane(plane).rect(dx,dy,centered=False).extrude(dz)
    elif kind == "cylinder":
        xdir = [B[i][0] for i in range(3)]
        axis = [B[i][2] for i in range(3)]
        origin = [center[i] + s["zmin"] * axis[i] for i in range(3)]
        plane = cq.Plane(origin=origin, xDir=xdir, normal=axis)
        result = cq.Workplane(plane).circle(s["radius"]).extrude(s["zmax"]-s["zmin"])
    else:
        raise ValueError(kind)
    cq.exporters.export(result, str(OUT / "reconstructed.step"))
    cq.exporters.export(result, str(OUT / "reconstructed.stl"), tolerance=0.001, angularTolerance=0.05)
    return result

if __name__ == "__main__":
    build()
